48	    export class SummaryPanel {
49	      readonly seats = input.required<SelectedSeatSummary[]>();
50	      readonly totalPrice = input.required<number>();
51	      readonly soldOut = input<boolean>(false);
52	
53	      protected readonly expanded = signal(false);
54	
55	      protected readonly formatEuroAmount = formatEuroAmount;
56	
57	      protected toggleExpanded(): void {
58	        this.expanded.update((value) => !value);
59	      }
60	    }
