68	      } @else {
69	        <button
70	          type="button"
71	          class="summary-panel__toggle"
72	          (click)="toggleExpanded()"
73	          [attr.aria-expanded]="expanded()"
74	        >
75	          <span class="summary-panel__toggle-count">
76	            {{ seats().length }} {{ seats().length === 1 ? 'Platz' : 'Plätze' }} ausgewählt
77	          </span>
78	          <span class="summary-panel__toggle-total">{{ formatEuroAmount(totalPrice()) }}</span>
79	        </button>
80	
81	        <div class="summary-panel__content">
82	          @if (seats().length === 0) {
83	            <p class="summary-panel__empty">Noch keine Plätze ausgewählt.</p>
84	          } @else {
85	            <ul class="summary-panel__list">
86	              @for (seat of seats(); track seat.seatId) {
87	                <li class="summary-panel__item">
88	                  <span class="summary-panel__item-label">
