import { Component, input, model } from '@angular/core';

import { VenueListItem } from '../../../core/models/venue.model';

@Component({
  selector: 'app-filter-bar',
  imports: [],
  templateUrl: './filter-bar.html',
  styleUrl: './filter-bar.scss'
})
export class FilterBar {
  readonly von = model<string | null>(null);
  readonly bis = model<string | null>(null);
  readonly venueId = model<string | null>(null);
  readonly venues = input<VenueListItem[]>([]);

  onVonChange(value: string): void {
    this.von.set(value === '' ? null : value);
  }

  onBisChange(value: string): void {
    this.bis.set(value === '' ? null : value);
  }

  onVenueChange(value: string): void {
    this.venueId.set(value === '' ? null : value);
  }
}
<div class="filter-bar">
  <div class="filter-bar__field-group">
    <div class="filter-bar__field">
      <label class="filter-bar__label" for="filter-bar-von">Von</label>
      <input
        id="filter-bar-von"
        class="filter-bar__input"
        type="date"
        [value]="von() ?? ''"
        (change)="onVonChange($any($event.target).value)"
      />
    </div>
    <div class="filter-bar__field">
      <label class="filter-bar__label" for="filter-bar-bis">Bis</label>
      <input
        id="filter-bar-bis"
        class="filter-bar__input"
        type="date"
        [value]="bis() ?? ''"
        (change)="onBisChange($any($event.target).value)"
      />
    </div>
  </div>
  <div class="filter-bar__field">
    <label class="filter-bar__label" for="filter-bar-venue">Spielstätte</label>
    <select
      id="filter-bar-venue"
      class="filter-bar__input"
      [value]="venueId() ?? ''"
      (change)="onVenueChange($any($event.target).value)"
    >
      <option value="">Alle Spielstätten</option>
      @for (venue of venues(); track venue.id) {
        <option [value]="venue.id">{{ venue.name }}</option>
      }
    </select>
  </div>
</div>

