4	import { PriceCategory, Seat as SeatModel, SeatMap } from '../../../core/models/seat-map.model';
5	import { Seat } from '../seat/seat';
6	import { PriceCategoryPanel } from '../price-category-panel/price-category-panel';
7	import { SelectedSeatSummary, SummaryPanel } from '../summary-panel/summary-panel';
8	
9	interface GridCell {
10	  type: 'seat' | 'aisle';
11	  seat?: SeatModel;
12	}
13	
14	interface Point {
15	  x: number;
16	  y: number;
17	}
18	
19	const MIN_ZOOM = 0.5;
20	const MAX_ZOOM = 3;
21	const PLACEHOLDER_ROWS = 8;
22	const PLACEHOLDER_COLUMNS = 10;
23	
24	function distance(a: Point, b: Point): number {
25	  return Math.hypot(a.x - b.x, a.y - b.y);
26	}
27	
28	function midpoint(a: Point, b: Point): Point {
29	  return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
30	}
31	
32	function clamp(value: number, min: number, max: number): number {
33	  return Math.min(max, Math.max(min, value));
34	}
