36	@Component({
37	  selector: 'app-sitzplan-page',
38	  imports: [Seat, PriceCategoryPanel, SummaryPanel],
39	  templateUrl: './sitzplan-page.html',
40	  styleUrl: './sitzplan-page.scss'
41	})
42	export class SitzplanPage {
43	  private readonly seatMapService = inject(SeatMapService);
44	
45	  readonly id = input.required<string>();
46	
47	  protected readonly seatMap = signal<SeatMap | null>(null);
48	  protected readonly loadError = signal(false);
49	  protected readonly selectedSeatIds = signal<ReadonlySet<string>>(new Set());
50	  protected readonly focusedSeatId = signal<string | null>(null);
51	  protected readonly assignedCategoryId = signal<ReadonlyMap<string, string>>(new Map());
52	  private readonly panelDismissed = signal(false);
53	  private readonly seatComponents = viewChildren(Seat);
54	
55	  protected readonly priceCategories = computed(() => this.seatMap()?.priceCategories ?? []);
56	
57	  protected readonly panelSeatId = computed<string | null>(() => {
58	    const id = this.focusedSeatId();
59	    if (!id || this.panelDismissed() || this.priceCategories().length <= 1) {
60	      return null;
61	    }
62	    return this.selectedSeatIds().has(id) ? id : null;
63	  });
64	
65	  protected readonly panelSeatRow = computed<string | null>(() => {
66	    const id = this.panelSeatId();
67	    return id ? (this.seatMap()?.seats.find((s) => s.seatId === id)?.row ?? null) : null;
68	  });
69	
70	  protected readonly zoom = signal(1);
71	  protected readonly panX = signal(0);
72	  protected readonly panY = signal(0);
73	
74	  protected readonly transform = computed(() => `translate(${this.panX()}px, ${this.panY()}px) scale(${this.zoom()})`);
75	
76	  protected readonly columnNumbers = computed<number[]>(() => {
77	    const map = this.seatMap();
78	    return map ? Array.from({ length: map.columns }, (_, index) => index + 1) : [];
79	  });
80	
81	  private readonly seatByPosition = computed<Map<string, SeatModel>>(() => {
82	    const seatByPosition = new Map<string, SeatModel>();
83	    for (const seat of this.seatMap()?.seats ?? []) {
84	      seatByPosition.set(`${seat.row}:${seat.column}`, seat);
85	    }
86	    return seatByPosition;
87	  });
88	
89	  protected readonly rowsWithCells = computed<{ row: string; cells: GridCell[] }[]>(() => {
90	    const map = this.seatMap();
91	    if (!map) {
92	      return [];
93	    }
94	
95	    const seatByPosition = this.seatByPosition();
96	    const aisleColumns = new Set(map.aisleColumns);
97	
98	    return map.rows.map((row) => ({
99	      row,
100	      cells: Array.from({ length: map.columns }, (_, index): GridCell => {
101	        const column = index + 1;
102	        if (aisleColumns.has(column)) {
103	          return { type: 'aisle' };
104	        }
105	        const seat = seatByPosition.get(`${row}:${column}`);
106	        return seat ? { type: 'seat', seat } : { type: 'aisle' };
107	      })
108	    }));
109	  });
110	
111	  protected readonly placeholderCells = Array.from({ length: PLACEHOLDER_ROWS * PLACEHOLDER_COLUMNS });
112	  protected readonly placeholderColumns = PLACEHOLDER_COLUMNS;
113	
114	  private readonly activePointers = new Map<number, Point>();
115	  private lastPanPoint: Point | null = null;
116	  private pinchStartDistance: number | null = null;
117	  private pinchStartZoom = 1;
118	  private pinchMidpoint: Point | null = null;
119	
120	  constructor() {
121	    effect((onCleanup) => {
122	      this.seatMap.set(null);
123	      this.loadError.set(false);
124	      this.selectedSeatIds.set(new Set());
125	      this.focusedSeatId.set(null);
126	      this.assignedCategoryId.set(new Map());
127	      this.panelDismissed.set(false);
128	
129	      const subscription = this.seatMapService.getSeatMap(this.id()).subscribe({
130	        next: (seatMap) => {
131	          this.seatMap.set(seatMap);
132	          this.setFocusedSeatId(seatMap.seats.find((s) => s.status === 'Free')?.seatId ?? null);
133	        },
134	        error: () => this.loadError.set(true)
135	      });
136	
137	      onCleanup(() => subscription.unsubscribe());
138	    });
139	  }
140	
141	  private setFocusedSeatId(seatId: string | null): void {
142	    this.focusedSeatId.set(seatId);
143	    this.panelDismissed.set(false);
144	  }
145	
146	  protected onSeatToggled(seatId: string): void {
147	    this.setFocusedSeatId(seatId);
148	    const wasSelected = this.selectedSeatIds().has(seatId);
149	
150	    this.selectedSeatIds.update((current) => {
151	      const next = new Set(current);
152	      if (next.has(seatId)) {
153	        next.delete(seatId);
154	      } else {
155	        next.add(seatId);
156	      }
157	      return next;
158	    });
159	
160	    if (wasSelected) {
161	      this.assignedCategoryId.update((current) => {
162	        const next = new Map(current);
163	        next.delete(seatId);
164	        return next;
165	      });
166	    } else if (this.priceCategories().length === 1) {
167	      const onlyCategoryId = this.priceCategories()[0].id;
168	      this.assignedCategoryId.update((current) => new Map(current).set(seatId, onlyCategoryId));
169	    }
170	  }
171	
172	  protected onCategoryChosen(seatId: string, categoryId: string): void {
173	    this.assignedCategoryId.update((current) => new Map(current).set(seatId, categoryId));
174	  }
175	
176	  protected categoryOf(seatId: string): PriceCategory | undefined {
177	    const categoryId = this.assignedCategoryId().get(seatId);
178	    return categoryId ? this.priceCategories().find((c) => c.id === categoryId) : undefined;
179	  }
180	
181	  protected readonly selectedSeatSummaries = computed<SelectedSeatSummary[]>(() => {
182	    const map = this.seatMap();
183	    if (!map) {
184	      return [];
185	    }
186	    return Array.from(this.selectedSeatIds())
187	      .map((seatId) => map.seats.find((s) => s.seatId === seatId))
188	      .filter((seat): seat is SeatModel => seat !== undefined)
189	      .map((seat) => {
190	        const category = this.categoryOf(seat.seatId);
191	        return {
192	          seatId: seat.seatId,
193	          row: seat.row,
194	          column: seat.column,
195	          categoryName: category?.name ?? null,
196	          price: category?.price ?? 0
197	        };
198	      })
199	      .sort((a, b) => a.row.localeCompare(b.row) || a.column - b.column);
200	  });
201	
202	  protected readonly totalPrice = computed<number>(() => {
203	    const totalCents = this.selectedSeatSummaries().reduce(
204	      (sum, seat) => sum + Math.round(seat.price * 100),
205	      0
206	    );
207	    return totalCents / 100;
208	  });
209	
210	  protected readonly soldOut = computed<boolean>(() => {
211	    const map = this.seatMap();
212	    return map !== null && map.seats.length > 0 && !map.seats.some((seat) => seat.status === 'Free');
213	  });
214	
215	  protected onGridKeydown(event: KeyboardEvent): void {
216	    if (event.key === 'Escape') {
217	      const seatId = this.panelSeatId();
218	      if (seatId) {
219	        event.preventDefault();
220	        this.panelDismissed.set(true);
221	        const seat = this.seatMap()?.seats.find((s) => s.seatId === seatId);
222	        if (seat) {
223	          this.seatComponents()
224	            .find((s) => s.row() === seat.row && s.column() === seat.column)
225	            ?.focusSeat();
226	        }
227	      }
228	      return;
229	    }
230	
231	    const map = this.seatMap();
232	    const current = map?.seats.find((s) => s.seatId === this.focusedSeatId());
233	    if (!map || !current) {
234	      return;
235	    }
236	
237	    const rowIndex = map.rows.indexOf(current.row);
238	    let nextSeat: SeatModel | undefined;
239	
240	    switch (event.key) {
241	      case 'ArrowRight':
242	        for (let c = current.column + 1; c <= map.columns && !nextSeat; c++) {
243	          nextSeat = this.selectableSeatAt(current.row, c);
244	        }
245	        break;
246	      case 'ArrowLeft':
247	        for (let c = current.column - 1; c >= 1 && !nextSeat; c--) {
248	          nextSeat = this.selectableSeatAt(current.row, c);
249	        }
250	        break;
251	      case 'ArrowDown':
252	        for (let r = rowIndex + 1; r < map.rows.length && !nextSeat; r++) {
253	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
254	        }
255	        break;
256	      case 'ArrowUp':
257	        for (let r = rowIndex - 1; r >= 0 && !nextSeat; r--) {
258	          nextSeat = this.selectableSeatAt(map.rows[r], current.column);
259	        }
260	        break;
261	      default:
262	        return;
263	    }
264	
265	    event.preventDefault();
266	    if (nextSeat) {
267	      this.setFocusedSeatId(nextSeat.seatId);
268	      this.seatComponents()
269	        .find((s) => s.row() === nextSeat!.row && s.column() === nextSeat!.column)
270	        ?.focusSeat();
271	    }
272	  }
273	
274	  private selectableSeatAt(row: string, column: number): SeatModel | undefined {
275	    const seat = this.seatByPosition().get(`${row}:${column}`);
276	    return seat?.status === 'Free' ? seat : undefined;
277	  }
278	
279	  protected onWheel(event: WheelEvent): void {
280	    event.preventDefault();
281	    if (event.deltaY === 0) {
282	      return;
283	    }
284	    const delta = event.deltaY > 0 ? -0.1 : 0.1;
285	    this.zoom.set(clamp(this.zoom() + delta, MIN_ZOOM, MAX_ZOOM));
286	  }
287	
288	  protected onPointerDown(event: PointerEvent): void {
289	    (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId);
290	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
291	
292	    if (this.activePointers.size === 1) {
293	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
294	    } else if (this.activePointers.size === 2) {
295	      const [a, b] = Array.from(this.activePointers.values());
296	      this.pinchStartDistance = distance(a, b);
297	      this.pinchStartZoom = this.zoom();
298	      this.pinchMidpoint = midpoint(a, b);
299	    }
300	  }
301	
302	  protected onPointerMove(event: PointerEvent): void {
303	    if (!this.activePointers.has(event.pointerId)) {
304	      return;
305	    }
306	    this.activePointers.set(event.pointerId, { x: event.clientX, y: event.clientY });
307	
308	    if (this.activePointers.size === 2 && this.pinchStartDistance !== null && this.pinchMidpoint !== null) {
309	      const [a, b] = Array.from(this.activePointers.values());
310	      const currentDistance = distance(a, b);
311	      this.zoom.set(clamp(this.pinchStartZoom * (currentDistance / this.pinchStartDistance), MIN_ZOOM, MAX_ZOOM));
312	
313	      const currentMidpoint = midpoint(a, b);
314	      this.panX.update((x) => x + (currentMidpoint.x - this.pinchMidpoint!.x));
315	      this.panY.update((y) => y + (currentMidpoint.y - this.pinchMidpoint!.y));
316	      this.pinchMidpoint = currentMidpoint;
317	    } else if (this.activePointers.size === 1 && event.buttons > 0 && this.lastPanPoint) {
318	      this.panX.update((x) => x + (event.clientX - this.lastPanPoint!.x));
319	      this.panY.update((y) => y + (event.clientY - this.lastPanPoint!.y));
320	      this.lastPanPoint = { x: event.clientX, y: event.clientY };
321	    }
322	  }
323	
324	  protected onPointerUp(event: PointerEvent): void {
325	    (event.currentTarget as HTMLElement).releasePointerCapture?.(event.pointerId);
326	    this.activePointers.delete(event.pointerId);
327	
328	    if (this.activePointers.size < 2) {
329	      this.pinchStartDistance = null;
330	      this.pinchMidpoint = null;
331	    }
332	
333	    if (this.activePointers.size === 0) {
334	      this.lastPanPoint = null;
335	    } else {
336	      const [remaining] = Array.from(this.activePointers.values());
337	      this.lastPanPoint = remaining;
338	    }
339	  }
340	}
341

